-- ----------------------------
-- Table structure for `sch_job_entity`
-- ----------------------------
DROP TABLE IF EXISTS `sch_job_entity`;
CREATE TABLE `sch_job_entity` (
  `CODE_` varchar(64) NOT NULL COMMENT '任务编码',
  `NAME_` varchar(256) DEFAULT NULL COMMENT '任务名称',
  `CALENDAR_CODE_` varchar(200) DEFAULT NULL COMMENT '日历',
  `GROUP_CODE_` varchar(64) DEFAULT NULL COMMENT '任务类型',
  `JOB_TYPE1_` varchar(64) DEFAULT NULL COMMENT '任务类型1:\r\n            CONCURRENT - 并行\r\n            BLOCK - 串行\r\n            默认为串行',
  `JOB_TYPE2_` varchar(64) DEFAULT NULL COMMENT '任务类型2:\r\n            STATEFUL - 有\r\n            STATELESS - 无\r\n            默认为无',
  `NODE_SCOPE_TYPE_` varchar(64) DEFAULT NULL COMMENT 'CLUSTER -  集群\r\n            NODE - 节点',
  `NODE_SCOPE_` varchar(2000) DEFAULT NULL COMMENT '节点范围, 以逗号隔开',
  `NODE_STRATEGY_` varchar(64) DEFAULT NULL COMMENT '节点算法:\r\n            SMART - 智能选择\r\n            HASH - 一次性哈希\r\n            BALANCE - 负载均衡',
  `START_DATE_` date DEFAULT NULL COMMENT '开始日期',
  `END_DATE_` date DEFAULT NULL COMMENT '结束日期',
  `TIMEOUT_` int(11) DEFAULT NULL COMMENT '超时时间',
  `TIMEOUT_UNIT_` varchar(64) DEFAULT NULL COMMENT '超时时间单位:\r\n            H - 小时 1-23\r\n            M - 分钟 1 - 59',
  `TIMEOUT_INSTRUCTION_` varchar(64) DEFAULT NULL COMMENT '超时处理:\r\n            REDO - 重做\r\n            ABANDON - 放弃',
  `ERROR_INSTRUCTION_` varchar(64) DEFAULT NULL COMMENT '失败处理:\r\n            REDO - 重做\r\n            ABANDON - 放弃\r\n            PAUSE - 暂停\r\n            STOP - 终止',
  `PRIORITY_` int(11) DEFAULT NULL COMMENT '优先级:1 - 10',
  `CRON_EXPRESSION_` varchar(256) DEFAULT NULL COMMENT '任务表达式',
  `PARAM_` varchar(2000) DEFAULT NULL COMMENT '任务参数:JSON字符串。',
  `STATUS_` varchar(64) DEFAULT NULL COMMENT '状态:\r\n            DRAFT - 草稿\r\n            RUN - 运行中\r\n            COMPLETE - 完成\r\n            PAUSE - 暂停\r\n            STOP - 终止',
  `REMARK_` varchar(512) DEFAULT NULL COMMENT '备注',
  `TENANT_ID_` varchar(64) DEFAULT NULL COMMENT '租户',
  `CREATED_BY_ID_` varchar(64) DEFAULT NULL COMMENT '创建人ID',
  `CREATED_BY_NAME_` varchar(64) DEFAULT NULL COMMENT '创建人名称',
  `CREATED_TIME_` datetime DEFAULT NULL COMMENT '创建时间',
  `DELFLAG_` varchar(1) DEFAULT NULL COMMENT '逻辑删除标记',
  `DISPLAY_ORDER_` int(11) DEFAULT NULL COMMENT '显示序号',
  `MODIFIED_BY_ID_` varchar(64) DEFAULT NULL COMMENT '修改人ID',
  `MODIFIED_BY_NAME_` varchar(64) DEFAULT NULL COMMENT '修改人名称',
  `MODIFIED_TIME_` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `VERSION_` int(11) DEFAULT NULL COMMENT '版本',
  PRIMARY KEY (`CODE_`),
  KEY `SCH_FK_Reference_5` (`GROUP_CODE_`),
  CONSTRAINT `SCH_FK_Reference_5` FOREIGN KEY (`GROUP_CODE_`) REFERENCES `sch_job_group` (`CODE_`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='调度任务管理';

-- ----------------------------
-- Records of sch_job_entity
-- ----------------------------

-- ----------------------------
-- Table structure for `sch_job_group`
-- ----------------------------
DROP TABLE IF EXISTS `sch_job_group`;
CREATE TABLE `sch_job_group` (
  `CODE_` varchar(64) NOT NULL COMMENT '类别编码',
  `NAME_` varchar(256) DEFAULT NULL COMMENT '类别名称',
  `PARAM_` varchar(2000) DEFAULT NULL COMMENT '参数',
  `REMARK_` varchar(512) DEFAULT NULL COMMENT '描述',
  `TENANT_ID_` varchar(64) DEFAULT NULL COMMENT '租户',
  `CREATED_BY_ID_` varchar(64) DEFAULT NULL COMMENT '创建人ID',
  `CREATED_BY_NAME_` varchar(64) DEFAULT NULL COMMENT '创建人名称',
  `CREATED_TIME_` datetime DEFAULT NULL COMMENT '创建时间',
  `DELFLAG_` varchar(1) DEFAULT NULL COMMENT '逻辑删除标记',
  `DISPLAY_ORDER_` int(11) DEFAULT NULL COMMENT '显示序号',
  `MODIFIED_BY_ID_` varchar(64) DEFAULT NULL COMMENT '修改人ID',
  `MODIFIED_BY_NAME_` varchar(64) DEFAULT NULL COMMENT '修改人名称',
  `MODIFIED_TIME_` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `VERSION_` int(11) DEFAULT NULL COMMENT '版本',
  PRIMARY KEY (`CODE_`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='调度类型';

-- ----------------------------
-- Records of sch_job_group
-- ----------------------------

-- ----------------------------
-- Table structure for `sch_job_group_cluster`
-- ----------------------------
DROP TABLE IF EXISTS `sch_job_group_cluster`;
CREATE TABLE `sch_job_group_cluster` (
  `ID_` varchar(64) NOT NULL COMMENT 'ID',
  `GROUP_CODE_` varchar(64) NOT NULL COMMENT '类别编码',
  `CLUSTER_CODE_` varchar(64) NOT NULL COMMENT '服务器编码',
  `TENANT_ID_` varchar(64) DEFAULT NULL COMMENT '租户',
  `CREATED_BY_ID_` varchar(64) DEFAULT NULL COMMENT '创建人ID',
  `CREATED_BY_NAME_` varchar(64) DEFAULT NULL COMMENT '创建人名称',
  `CREATED_TIME_` datetime DEFAULT NULL COMMENT '创建时间',
  `DELFLAG_` varchar(1) DEFAULT NULL COMMENT '逻辑删除标记',
  `DISPLAY_ORDER_` int(11) DEFAULT NULL COMMENT '显示序号',
  `MODIFIED_BY_ID_` varchar(64) DEFAULT NULL COMMENT '修改人ID',
  `MODIFIED_BY_NAME_` varchar(64) DEFAULT NULL COMMENT '修改人名称',
  `MODIFIED_TIME_` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `VERSION_` int(11) DEFAULT NULL COMMENT '版本',
  PRIMARY KEY (`ID_`),
  KEY `SCH_FK_Reference_2` (`CLUSTER_CODE_`),
  KEY `SCH_FK_Reference_3` (`GROUP_CODE_`),
  CONSTRAINT `SCH_FK_Reference_2` FOREIGN KEY (`CLUSTER_CODE_`) REFERENCES `sch_cluster` (`CODE_`),
  CONSTRAINT `SCH_FK_Reference_3` FOREIGN KEY (`GROUP_CODE_`) REFERENCES `sch_job_group` (`CODE_`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='调度类型集群表';

-- ----------------------------
-- Records of sch_job_group_cluster
-- ----------------------------

-- ----------------------------
-- Table structure for `sch_job_inst`
-- ----------------------------
DROP TABLE IF EXISTS `sch_job_inst`;
CREATE TABLE `sch_job_inst` (
  `ID_` varchar(64) NOT NULL COMMENT 'ID',
  `JOB_CODE_` varchar(64) DEFAULT NULL COMMENT '任务编码',
  `JOB_NAME_` varchar(256) DEFAULT NULL COMMENT '任务名称',
  `GROUP_CODE_` varchar(64) DEFAULT NULL COMMENT '任务类型',
  `NODE_CODE_` varchar(64) DEFAULT NULL COMMENT '节点编码',
  `CLUSTER_CODE_` varchar(64) DEFAULT NULL COMMENT '集群编码',
  `ORIGIN_START_TIME_` datetime DEFAULT NULL COMMENT '初始开始时间',
  `START_TIME` datetime DEFAULT NULL COMMENT '开始时间',
  `END_TIME` datetime DEFAULT NULL COMMENT '结束时间',
  `EXEC_TIME_` bigint(20) DEFAULT NULL COMMENT '执行时间',
  `STATUS_` varchar(64) DEFAULT NULL COMMENT '状态:\r\n            NEW - 新建\r\n            NOTIFYING - 通知中\r\n            EXECUTING  执行中\r\n            DONE - 执行完成\r\n            ERROR - 执行失败',
  `TIMEOUT_TIMES_` int(10) DEFAULT NULL COMMENT '超时次数',
  `ERROR_TIMES_` int(10) DEFAULT NULL COMMENT '错误次数',
  `ERROR_MESSAGE_` varchar(500) DEFAULT NULL COMMENT '错误原因',
  `RECOVERED_` varchar(60) DEFAULT NULL COMMENT '是否恢复',
  `TRIGGER_KEY_` varchar(256) DEFAULT NULL COMMENT '触发器',
  `LAST_TRIGGER_KEY_` varchar(256) DEFAULT NULL COMMENT '上次触发器',
  `SCHEDULED_FIRE_TIME_` bigint(20) DEFAULT NULL COMMENT '计划触发时间',
  `SERVER_INSTANCE_ID_` varchar(64) DEFAULT NULL COMMENT '实例ID',
  `TENANT_ID_` varchar(64) DEFAULT NULL COMMENT '租户',
  `CREATED_BY_ID_` varchar(64) DEFAULT NULL COMMENT '创建人ID',
