-- ----------------------------
-- Table structure for `sch_node_state`
-- ----------------------------
DROP TABLE IF EXISTS `sch_node_state`;
CREATE TABLE `sch_node_state` (
  `CODE_` varchar(64) NOT NULL COMMENT '节点编码',
  `NAME_` varchar(256) DEFAULT NULL COMMENT '节点名称',
  `CLUSTER_CODE_` varchar(64) DEFAULT NULL COMMENT '集群编码',
  `CLUSTER_NAME_` varchar(256) DEFAULT NULL COMMENT '集群名称',
  `IP_ADDR_` varchar(64) DEFAULT NULL COMMENT 'IP地址',
  `PORT_` int(11) DEFAULT NULL COMMENT '端口',
  `WEB_CONTEXT_` varchar(64) DEFAULT NULL COMMENT '应用上下文',
  `STATUS_` varchar(64) DEFAULT NULL COMMENT '状态:\r\n            ONLINE - 在线\r\n            CONNECTING - 连接中\r\n            OFFLINE - 断开',
  `RETRY_TIMES_` int(11) DEFAULT NULL COMMENT '重试次数',
  `JOB_COUNT_` int(11) DEFAULT NULL COMMENT '运行任务数',
  `TOTAL_JVM_MEMORY_` bigint(20) DEFAULT NULL COMMENT 'JVM大小',
  `FREE_JVM_MEMORY_` bigint(20) DEFAULT NULL COMMENT '空闲JVM',
  `MEMORY_USAGE_` decimal(22,8) DEFAULT NULL COMMENT '内存使用',
  `DISK_USAGE_` decimal(22,8) DEFAULT NULL COMMENT '硬盘使用',
  `CPU_USAGE_` decimal(22,8) DEFAULT NULL COMMENT 'CPU使用',
  `LOCK_` varchar(64) DEFAULT NULL COMMENT '锁定:Y锁定/N未锁定',
  `LOCK_INSTANCE_ID_` varchar(64) DEFAULT NULL COMMENT '实例ID',
  `LOCK_TIME_` datetime DEFAULT NULL COMMENT '锁定时间',
  `LOCK_EXPIRE_TIME_` datetime DEFAULT NULL COMMENT '超时时间',
  `TENANT_ID_` varchar(64) DEFAULT NULL COMMENT '租户',
  `CREATED_BY_ID_` varchar(64) DEFAULT NULL COMMENT '创建人ID',
  `CREATED_BY_NAME_` varchar(64) DEFAULT NULL COMMENT '创建人名称',
  `CREATED_TIME_` datetime DEFAULT NULL COMMENT '创建时间',
  `DELFLAG_` varchar(1) DEFAULT NULL COMMENT '逻辑删除标记',
  `DISPLAY_ORDER_` int(11) DEFAULT NULL COMMENT '显示序号',
  `MODIFIED_BY_ID_` varchar(64) DEFAULT NULL COMMENT '修改人ID',
  `MODIFIED_BY_NAME_` varchar(64) DEFAULT NULL COMMENT '修改人名称',
  `MODIFIED_TIME_` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `VERSION_` int(11) DEFAULT NULL COMMENT '版本',
  PRIMARY KEY (`CODE_`),
  CONSTRAINT `SCH_FK_Reference_4` FOREIGN KEY (`CODE_`) REFERENCES `sch_node` (`CODE_`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='集群节点状态表';

