CREATE TABLE `wf_notification` (
  `ID` int(11) NOT NULL AUTO_INCREMENT,
  `TASK_ID` varchar(255) DEFAULT NULL,
  `OP_TIME` date DEFAULT NULL,
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

